import {definePrototype} from '@proto.ui/core';
export default definePrototype({name:'raw-alias-consumer',setup(def){
  def.expose.event('inspection',{payload:'json'});
  def.lifecycle.onMounted(run=>{
    const raw=run.props.getRaw();
    run.expose.emit('inspection',{phase:'mounted',stable:raw===run.props.getRaw()});
  });
  def.props.watchRawAll((run,next,prev)=>{
    run.expose.emit('inspection',{phase:'watch',current:next===run.props.getRaw(),distinct:next!==prev});
  });
  return r=>r.el('output','Raw alias consumer');
}});

