import {definePrototype} from '@proto.ui/core';import {KEY} from './keys';
export default definePrototype({name:'root-review-context-consumer',setup(def){
 const count=def.state.numberDiscrete('context.current',-1);def.expose.state('count',count);
 def.context.subscribe(KEY);def.lifecycle.onCreated(run=>{count.set(run.context.read(KEY).value);});
 return r=>r.el('output',r.read.context.read(KEY).value);
}});

